/// Raven `G_BoundsOverlap`.
///
/// Pure logic: checks if two 3D bounds overlap by comparing component-wise
/// min/max values. NOTE: flush up against counts as overlapping (equality
/// compares use `<=`/`>=`).
///
/// Source: `oracle/oracle/codemp/game/NPC_goal.c:94-115`
pub fn G_BoundsOverlap(
    mins1: vec3_t,
    maxs1: vec3_t,
    mins2: vec3_t,
    maxs2: vec3_t,
) -> qboolean {
    // Check if mins1 is beyond maxs2 on any axis
    if mins1[0] > maxs2[0] {
        return qfalse;
    }
    if mins1[1] > maxs2[1] {
        return qfalse;
    }
    if mins1[2] > maxs2[2] {
        return qfalse;
    }

    // Check if maxs1 is before mins2 on any axis
    if maxs1[0] < mins2[0] {
        return qfalse;
    }
    if maxs1[1] < mins2[1] {
        return qfalse;
    }
    if maxs1[2] < mins2[2] {
        return qfalse;
    }

    qtrue
}

